//! Engine.IO v4 / Socket.IO v4 framing and validation helpers.
//!
//! Ports the frame handling of selfhost/server.py: the `42[ack]...` event
//! encoding, the `451-[ack]-...` binary event encoding with a single
//! attachment sent as the next WebSocket frame, and the shared validation
//! helpers (16-hex device IDs, response envelopes).

use serde_json::{Value, json};

pub const MAX_SIGNAL: usize = 1024 * 1024;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Incoming {
    /// Engine.IO OPEN handshake is generated by us, not parsed.
    Ping,
    Pong(String),
    NamespaceConnect,
    NamespaceDisconnect,
    /// Plain Socket.IO event with optional ack id.
    Event { ack: Option<String>, name: String, args: Vec<Value> },
    /// Binary event: JSON header carried in text, attachment in next frame.
    BinaryEvent { ack: Option<String>, name: String, args: Vec<Value>, attachments_left: u32 },
    /// The binary attachment following a BinaryEvent header.
    Attachment(Vec<u8>),
    Other,
}

/// Parse one text frame. Returns the frame meaning; attachment bytes arrive
/// in the following binary frame, exactly like the Python reference.
pub fn parse_text(frame: &str) -> anyhow::Result<Incoming> {
    if frame == "2" || frame == "2{}".replace("{}", "") {
        return Ok(Incoming::Ping);
    }
    if frame == "2probe" {
        return Ok(Incoming::Ping);
    }
    if let Some(rest) = frame.strip_prefix('3') {
        return Ok(Incoming::Pong(rest.to_owned()));
    }
    if frame == "40" || frame == "40/" {
        return Ok(Incoming::NamespaceConnect);
    }
    if frame == "41" || frame == "41/" {
        return Ok(Incoming::NamespaceDisconnect);
    }
    if frame == "1" || frame == "0" {
        return Ok(Incoming::Other);
    }
    if let Some(rest) = frame.strip_prefix("45") {
        // 45<attachments>-[<ack>-]<json>
        let (count, rest) = rest
            .split_once('-')
            .ok_or_else(|| anyhow::anyhow!("invalid binary event header"))?;
        let attachments: u32 = count
            .parse()
            .map_err(|_| anyhow::anyhow!("invalid attachment count"))?;
        let (ack, rest) = split_ack(rest);
        let value: Value = serde_json::from_str(rest)
            .map_err(|_| anyhow::anyhow!("invalid JSON in binary event"))?;
        let (name, args) = split_event(value)?;
        return Ok(Incoming::BinaryEvent { ack, name, args, attachments_left: attachments });
    }
    if let Some(rest) = frame.strip_prefix("42") {
        let (ack, rest) = split_ack(rest);
        let value: Value = serde_json::from_str(rest)
            .map_err(|_| anyhow::anyhow!("invalid JSON in event"))?;
        let (name, args) = split_event(value)?;
        return Ok(Incoming::Event { ack, name, args });
    }
    Ok(Incoming::Other)
}

/// Parse one binary frame: Engine.IO messages start with the 0x04 marker.
pub fn parse_binary(frame: &[u8]) -> Incoming {
    if frame.first() == Some(&0x04) {
        Incoming::Attachment(frame[1..].to_vec())
    } else {
        Incoming::Other
    }
}

/// Socket.IO ack ids are bare digits right after the frame prefix:
/// "2[\"x\"]" -> (Some("2"), rest). Without ack: (None, rest).
fn split_ack(rest: &str) -> (Option<String>, &str) {
    let digits = rest
        .find(|c: char| !c.is_ascii_digit())
        .unwrap_or(rest.len());
    if digits == 0 {
        return (None, rest);
    }
    let head = &rest[..digits];
    match head.parse::<u64>() {
        Ok(_) => (Some(head.to_owned()), &rest[digits..]),
        Err(_) => (None, rest),
    }
}

fn split_event(value: Value) -> anyhow::Result<(String, Vec<Value>)> {
    match value {
        Value::Array(items) if !items.is_empty() => {
            let name = items[0]
                .as_str()
                .ok_or_else(|| anyhow::anyhow!("event name must be a string"))?
                .to_owned();
            Ok((name, items[1..].to_vec()))
        }
        _ => Err(anyhow::anyhow!("event payload must be an array")),
    }
}

pub fn encode_open(sid: &str, ping_interval: u64, ping_timeout: u64) -> String {
    format!("0{}", serde_json::to_string(&json!({
        "sid": sid,
        "upgrades": [],
        "pingInterval": ping_interval,
        "pingTimeout": ping_timeout,
        "maxPayload": MAX_SIGNAL,
    })).expect("fixed open payload"))
}

pub fn encode_namespace_connected(sid: &str) -> String {
    format!("40{}", serde_json::to_string(&json!({ "sid": sid })).expect("sid"))
}

/// 43<ack>[<json>]
pub fn encode_ack(ack: &str, args: &[Value]) -> String {
    format!("43{}{}", ack, serde_json::to_string(args).expect("ack args"))
}

/// 42<ack>["<name>",<args...>]
pub fn encode_event(name: &str, args: &[Value], ack: Option<&str>) -> String {
    let mut items = vec![Value::from(name)];
    items.extend(args.iter().cloned());
    let body = serde_json::to_string(&items).expect("event args");
    match ack {
        Some(id) => format!("42{id}{body}"),
        None => format!("42{body}"),
    }
}

/// Returns the text header plus the single binary attachment, mirroring
/// Python's `await peer.send("451-" + payload, b"\x04" + attachment)`.
pub fn encode_binary_event(name: &str, args: &[Value], attachment: &[u8]) -> (String, Vec<u8>) {
    let mut items = vec![Value::from(name)];
    items.extend(args.iter().cloned());
    let body = serde_json::to_string(&items).expect("binary event args");
    (format!("451-{body}"), [b"\x04".as_slice(), attachment].concat())
}

/// Response envelope used by every account REST route.
pub fn envelope(data: Option<Value>, code: i32, msg: &str) -> Value {
    json!({ "code": code, "msg": msg, "data": data })
}

/// 16 lowercase hex/alnum characters: the shared device-id shape.
pub fn valid_device_id(value: &str) -> bool {
    value.len() == 16
        && value.bytes().all(|b| b.is_ascii_lowercase() || b.is_ascii_digit())
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn parses_plain_events_with_and_without_ack() {
        let parsed = parse_text("421[\"room_info\"]").unwrap();
        match parsed {
            Incoming::Event { ack, name, args } => {
                assert_eq!(ack.as_deref(), Some("1"));
                assert_eq!(name, "room_info");
                assert!(args.is_empty());
            }
            other => panic!("wrong parse: {other:?}"),
        }
        let parsed = parse_text("42[\"leave\",{\"ice_id\":\"abc\"}]").unwrap();
        match parsed {
            Incoming::Event { ack, name, args } => {
                assert!(ack.is_none());
                assert_eq!(name, "leave");
                assert_eq!(args.len(), 1);
            }
            other => panic!("wrong parse: {other:?}"),
        }
    }

    #[test]
    fn parses_binary_event_header_and_attachment() {
        let parsed = parse_text("451-2[\"control\",{\"app_control_id\":\"app\"}]").unwrap();
        match parsed {
            Incoming::BinaryEvent { ack, name, args, attachments_left } => {
                assert_eq!(ack.as_deref(), Some("2"));
                assert_eq!(name, "control");
                assert_eq!(attachments_left, 1);
                assert_eq!(args[0]["app_control_id"], "app");
            }
            other => panic!("wrong parse: {other:?}"),
        }
        match parse_binary(b"\x04\x08\x01") {
            Incoming::Attachment(bytes) => assert_eq!(bytes, vec![0x08, 0x01]),
            other => panic!("wrong parse: {other:?}"),
        }
    }

    #[test]
    fn encodes_events_like_the_python_reference() {
        assert_eq!(encode_event("room_info", &[], Some("1")), "421[\"room_info\"]");
        assert_eq!(encode_event("leave", &[], None), "42[\"leave\"]");
        let (header, attachment) =
            encode_binary_event("be-controlled", &[json!({"ice_id": "i"})], b"payload");
        assert!(header.starts_with("451-[\"be-controlled\","));
        assert_eq!(attachment, b"\x04payload");
    }

    #[test]
    fn device_id_validation_matches_client() {
        assert!(valid_device_id("aeawvvwjgqbfcsbr"));
        assert!(!valid_device_id("short"));
        assert!(!valid_device_id("AEAWVVWJGQBFCSBR"));
        assert!(!valid_device_id("aeawvvwjgqbfcsbr0x"));
    }
}
